def zigzag_convert(s, num_rows):
    n = len(s)
    if num_rows <= 1 or num_rows >= n:
        return s
    cycle = 2 * (num_rows - 1)
    buckets = [[] for _ in range(num_rows)]
    for i, ch in enumerate(s):
        pos = i % cycle
        row = pos if pos < num_rows else cycle - pos
        buckets[row].append(ch)
    return ''.join(''.join(b) for b in buckets)

